<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\ThemeAsset\Domain\Gateway;

use Civi\Lughauth\Features\Document\ThemeAsset\Domain\ThemeAsset;

class ThemeAssetCursor
{
    public const string CODE_ASC = 'code';
    public const string CODE_DESC = '-code';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceCode = null,
        private ?array $order = null,
    ) {
    }
    public function next(ThemeAsset $themeAsset, ?int $size): ThemeAssetCursor
    {
        $next = clone $this;
        $next->sinceUid = $themeAsset->uid();
        $next->sinceCode = $themeAsset->getCode();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceCode(): ?string
    {
        return $this->sinceCode;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
